import React, { Component } from 'react'
//import Table from 'react-bootstrap/Table'
import Button from 'react-bootstrap/Button'
import Form from 'react-bootstrap/Form'
import Spinner from 'react-bootstrap/Spinner'
import DataTable from 'react-data-table-component'

class CommentersTable extends Component {


    handleChange = changeEvent => {
        console.log('Selected Rows: ', changeEvent.selectedRows);

          this.props.handleCommentersChange(changeEvent.selectedRows);
    }
    
    submitForm = () => {
        this.props.handleCommentersSubmit(this.state)
        //this.setState(this.initialState)
    }
    
    
    render() {
        
        const commenterData = this.props.commenterData
  
        const showCommentersTable = this.props.showCommentersTable ? {display: 'block'} : {display: 'none'};
        
        const showCommentersSubmitButton = this.props.showCommentersSubmitButton ? {display: 'block'} : {display: 'none'};
        const showCommentersSubmitLoadingButton = this.props.showCommentersSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
        
        const selectedCommenters = this.props.selectedCommenters;
        
        
        if (selectedCommenters.length > 0) {
          console.log('yes');
          this.setState({showCommentersSubmitButton: true});
        } else {
          this.setState({showCommentersSubmitButton: false});
        }
        
        const columns =  [
            { name: 'Profile URL', selector: 'profileUrl', sortable: true },
            { name: 'Messaged Before', selector: 'messagedBefore', sortable: true }
            ];
            
          
        return (
          
          <Form>
              <DataTable style={showCommentersTable}
                title="Commenters"
                columns={columns}
                data={commenterData}
                defaultSortField="messagedBefore"
                selectableRows
                onSelectedRowsChange={this.handleChange}
                highlightOnHover
              />
                       
             <Button
                type="submit"
                value="Submit"
                onClick={e => {e.preventDefault(); this.handleSubmit()}}
                style={showCommentersSubmitButton}>
                Submit
             </Button>
                  
              <Button variant="primary" disabled style={showCommentersSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                Loading...
              </Button>
                    
          </Form>
        )
    }

}

export default CommentersTable;
